window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cfebc6be27fb2711"]={"versions": [{"id": "FIG-cfebc6be27fb2711", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> PDU-Layout / Protokoll-Header-Spezifikation (Bit-/Byte-Felddefinition auf Protokollebene).</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li><strong>Plattform & Schicht:</strong> AUTOSAR Classic Platform (Release R3.2.3), Communication Stack (ComStack).</li>\n<li><strong>Modul:</strong> <code>FrArTp</code> (AUTOSAR FlexRay Transport Layer, Spezifikation SWS_FlexRayARTransportLayer nach ISO 10681-2).</li>\n<li><strong>Funktionale Einordnung:</strong> Liegt zwischen dem PDU Router (<code>PduR</code>) als oberer Schicht und dem FlexRay Interface (<code>FrIf</code>) als unterer Schicht.</li>\n<li><strong>Technischer Zweck:</strong> Definition des 32-Bit-Adress-Headers für N-PDUs im 2-Byte-Adressierungsmodus (<code>FRARTP_2_BYTE_ADDRESSING</code>). Dient der logischen Adressierung (Quell- und Ziel-Knotenidentifikation) für Punkt-zu-Punkt- (1:1) sowie Punkt-zu-Multipunkt-Verbindungen (1:n, funktional/Broadcast) über FlexRay-Netzwerke, typischerweise für Diagnosekommunikation (DoFR / UDS via ISO 14229) und Kalibrierung (XCP on FlexRay).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Dargestellte Datenstrukturen & Felder:</strong></li>\n<li><strong><code>Target Address (16 Bit)</code>:</strong></li>\n<li><strong>Größe:</strong> 2 Byte (16 Bit).</li>\n<li><strong>Position:</strong> Byte 0 und Byte 1 des Adress-Headers.</li>\n<li><strong>Codierung:</strong> Big-Endian (Network Byte Order, MSB in Byte 0, LSB in Byte 1).</li>\n<li><strong>Semantik:</strong> Logische 16-Bit-Zieladresse (Empfänger-Steuergerät bzw. funktionale Multicast-/Broadcast-Adresse).</li>\n<li><strong><code>Source Address (16 Bit)</code>:</strong></li>\n<li><strong>Größe:</strong> 2 Byte (16 Bit).</li>\n<li><strong>Position:</strong> Byte 2 und Byte 3 des Adress-Headers.</li>\n<li><strong>Codierung:</strong> Big-Endian (Network Byte Order, MSB in Byte 2, LSB in Byte 3).</li>\n<li><strong>Semantik:</strong> Logische 16-Bit-Quelladresse (sendendes Steuergerät).</li>\n<li><strong>Beziehungen, Framing & Kardinalitäten:</strong></li>\n<li><strong>Gesamtbreite des Adress-Headers:</strong> Exakt 4 Byte.</li>\n<li><strong>Kardinalität:</strong> 1:1-Paarung pro adressiertem N-PDU-Rahmen. Jeder Adress-Header besteht obligatorisch aus genau einer Target Address und genau einer Source Address.</li>\n<li><strong>PDU-Strukturierung:</strong> Der Adress-Header steht unmittelbar am Anfang der N-PDU, gefolgt von der Protocol Control Information (N-PCI) und den Nutzdaten (N-Data):</li>\n</ul>\n<p class=\"fig-p\">$$\\text{N-PDU} = \\text{Address Header (4 Bytes)} + \\text{N-PCI (1–5 Bytes)} + \\text{N-Data}$$</p>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Sende-Pfad (TX):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>PduR</code> initiiert die Übertragung via <code>PduR_FrArTpTransmit(TxPduId, PduInfoPtr)</code>.</li>\n<li><strong>Header-Generierung:</strong> Das Modul <code>FrArTp</code> prüft die für die Verbindung (<code>FrArTpConnection</code>) konfigurierte Adressierungsart. Bei aktivem 2-Byte-Format werden die konfigurierte Target Address (<code>FrArTpTargetAddress</code>) in Byte 0–1 und die Source Address (<code>FrArTpSourceAddress</code>) in Byte 2–3 des N-PDU-Puffers serialisiert.</li>\n<li><strong>Framing & N-PCI:</strong> Nachfolgend werden N-PCI (SF, FF, CF, FC) und SDU-Daten assembliert.</li>\n<li><strong>Übergabe:</strong> Die serialisierte PDU wird via <code>FrIf_Transmit(FrTxPduId, &amp;PduInfo)</code> an das FlexRay-Interface übergeben.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Empfangs-Pfad (RX) & Filterung:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Asynchrone Empfangsmeldung via <code>FrArTp_RxIndication(RxPduId, PduInfoPtr)</code> durch das <code>FrIf</code>.</li>\n<li><strong>Parsing:</strong> Extraktion von Byte 0–1 (TA) und Byte 2–3 (SA).</li>\n<li><strong>Adressfilterung:</strong> Abgleich von TA gegen die eigene konfigurierte Knotenadresse (physikalisch) oder Gruppenadressen (funktional).</li>\n<li><strong>Routing:</strong> Zuordnung zur entsprechenden RX-Verbindungsinstanz (<code>FrArTpRxConnection</code>) anhand des Tupels <code>(Target Address, Source Address)</code>.</li>\n<li><strong>Verwerfen/Fehlerfall:</strong> Passt TA nicht auf den lokalen Knoten oder ist kein passender Verbindungskontext konfiguriert, wird die PDU stillschweigend verworfen; bei Formatinkonsistenz oder PDU-Längenunterschreitung (< 4 Byte Adress-Header + N-PCI) erfolgt ein Report an das Default Error Tracer Modul (<code>DET</code>).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Nutzdaten-Overhead & PDU-Budgetierung:</strong></li>\n<li>Der 2-Byte-Adress-Header verbraucht stets <strong>4 Byte Payload</strong> pro FlexRay-Frame. Bei festen statischen Slotgrößen (z. B. 16, 32 oder 64 Bytes) reduziert sich die maximale Transportdatenlänge pro Frame (Single Frame oder Consecutive Frame) entsprechend um 4 Bytes plus N-PCI-Länge.</li>\n<li><strong>Endianness & Byte-Order:</strong></li>\n<li>AUTOSAR ComStack schreibt Network Byte Order (Big-Endian) vor. Treiber- und Stack-Entwickler müssen sicherstellen, dass 16-Bit-Ganzzahlwerte auf Little-Endian-Mikrocontrollern (z. B. ARM, TriCore) beim Serialisieren/Deserialisieren explizit gedreht werden.</li>\n<li><strong>Konfigurationsanforderungen (BSW/ECUC):</strong></li>\n<li>Parameter <code>FrArTpAddressFormatType</code>: Konfiguration auf <code>FRARTP_2_BYTE_ADDRESSING</code>.</li>\n<li>Konsistenz zwischen <code>FrArTpTargetAddress</code> / <code>FrArTpSourceAddress</code> und den korrespondierenden Modulen (<code>PduR</code>, <code>Dcm</code>, DoFR).</li>\n<li>Unterscheidung zum 1-Byte-Adressierungsmodus (<code>FRARTP_1_BYTE_ADDRESSING</code>): Das 2-Byte-Format erweitert den logischen Adressraum von 256 auf 65.536 Knoten, verdoppelt jedoch den Adress-Header-Overhead von 2 auf 4 Bytes.</li>\n</ul>"}, {"id": "FIG-8e478ed3be09459c", "releases": ["R4.1.3", "R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> PDU-Layout / Protokoll-Header-Spezifikation (Bit-/Byte-Felddefinition auf Protokollebene).</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li><strong>Plattform & Schicht:</strong> AUTOSAR Classic Platform (Release R3.2.3), Communication Stack (ComStack).</li>\n<li><strong>Modul:</strong> <code>FrArTp</code> (AUTOSAR FlexRay Transport Layer, Spezifikation SWS_FlexRayARTransportLayer nach ISO 10681-2).</li>\n<li><strong>Funktionale Einordnung:</strong> Liegt zwischen dem PDU Router (<code>PduR</code>) als oberer Schicht und dem FlexRay Interface (<code>FrIf</code>) als unterer Schicht.</li>\n<li><strong>Technischer Zweck:</strong> Definition des 32-Bit-Adress-Headers für N-PDUs im 2-Byte-Adressierungsmodus (<code>FRARTP_2_BYTE_ADDRESSING</code>). Dient der logischen Adressierung (Quell- und Ziel-Knotenidentifikation) für Punkt-zu-Punkt- (1:1) sowie Punkt-zu-Multipunkt-Verbindungen (1:n, funktional/Broadcast) über FlexRay-Netzwerke, typischerweise für Diagnosekommunikation (DoFR / UDS via ISO 14229) und Kalibrierung (XCP on FlexRay).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Dargestellte Datenstrukturen & Felder:</strong></li>\n<li><strong><code>Target Address (16 Bit)</code>:</strong></li>\n<li><strong>Größe:</strong> 2 Byte (16 Bit).</li>\n<li><strong>Position:</strong> Byte 0 und Byte 1 des Adress-Headers.</li>\n<li><strong>Codierung:</strong> Big-Endian (Network Byte Order, MSB in Byte 0, LSB in Byte 1).</li>\n<li><strong>Semantik:</strong> Logische 16-Bit-Zieladresse (Empfänger-Steuergerät bzw. funktionale Multicast-/Broadcast-Adresse).</li>\n<li><strong><code>Source Address (16 Bit)</code>:</strong></li>\n<li><strong>Größe:</strong> 2 Byte (16 Bit).</li>\n<li><strong>Position:</strong> Byte 2 und Byte 3 des Adress-Headers.</li>\n<li><strong>Codierung:</strong> Big-Endian (Network Byte Order, MSB in Byte 2, LSB in Byte 3).</li>\n<li><strong>Semantik:</strong> Logische 16-Bit-Quelladresse (sendendes Steuergerät).</li>\n<li><strong>Beziehungen, Framing & Kardinalitäten:</strong></li>\n<li><strong>Gesamtbreite des Adress-Headers:</strong> Exakt 4 Byte.</li>\n<li><strong>Kardinalität:</strong> 1:1-Paarung pro adressiertem N-PDU-Rahmen. Jeder Adress-Header besteht obligatorisch aus genau einer Target Address und genau einer Source Address.</li>\n<li><strong>PDU-Strukturierung:</strong> Der Adress-Header steht unmittelbar am Anfang der N-PDU, gefolgt von der Protocol Control Information (N-PCI) und den Nutzdaten (N-Data):</li>\n</ul>\n<p class=\"fig-p\">$$\\text{N-PDU} = \\text{Address Header (4 Bytes)} + \\text{N-PCI (1–5 Bytes)} + \\text{N-Data}$$</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Sende-Pfad (TX):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>PduR</code> initiiert die Übertragung via <code>PduR_FrArTpTransmit(TxPduId, PduInfoPtr)</code>.</li>\n<li><strong>Header-Generierung:</strong> Das Modul <code>FrArTp</code> prüft die für die Verbindung (<code>FrArTpConnection</code>) konfigurierte Adressierungsart. Bei aktivem 2-Byte-Format werden die konfigurierte Target Address (<code>FrArTpTargetAddress</code>) in Byte 0–1 und die Source Address (<code>FrArTpSourceAddress</code>) in Byte 2–3 des N-PDU-Puffers serialisiert.</li>\n<li><strong>Framing & N-PCI:</strong> Nachfolgend werden N-PCI (SF, FF, CF, FC) und SDU-Daten assembliert.</li>\n<li><strong>Übergabe:</strong> Die serialisierte PDU wird via <code>FrIf_Transmit(FrTxPduId, &amp;PduInfo)</code> an das FlexRay-Interface übergeben.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Empfangs-Pfad (RX) & Filterung:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Asynchrone Empfangsmeldung via <code>FrArTp_RxIndication(RxPduId, PduInfoPtr)</code> durch das <code>FrIf</code>.</li>\n<li><strong>Parsing:</strong> Extraktion von Byte 0–1 (TA) und Byte 2–3 (SA).</li>\n<li><strong>Adressfilterung:</strong> Abgleich von TA gegen die eigene konfigurierte Knotenadresse (physikalisch) oder Gruppenadressen (funktional).</li>\n<li><strong>Routing:</strong> Zuordnung zur entsprechenden RX-Verbindungsinstanz (<code>FrArTpRxConnection</code>) anhand des Tupels <code>(Target Address, Source Address)</code>.</li>\n<li><strong>Verwerfen/Fehlerfall:</strong> Passt TA nicht auf den lokalen Knoten oder ist kein passender Verbindungskontext konfiguriert, wird die PDU stillschweigend verworfen; bei Formatinkonsistenz oder PDU-Längenunterschreitung (< 4 Byte Adress-Header + N-PCI) erfolgt ein Report an das Default Error Tracer Modul (<code>DET</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Nutzdaten-Overhead & PDU-Budgetierung:</strong></li>\n<li>Der 2-Byte-Adress-Header verbraucht stets <strong>4 Byte Payload</strong> pro FlexRay-Frame. Bei festen statischen Slotgrößen (z. B. 16, 32 oder 64 Bytes) reduziert sich die maximale Transportdatenlänge pro Frame (Single Frame oder Consecutive Frame) entsprechend um 4 Bytes plus N-PCI-Länge.</li>\n<li><strong>Endianness & Byte-Order:</strong></li>\n<li>AUTOSAR ComStack schreibt Network Byte Order (Big-Endian) vor. Treiber- und Stack-Entwickler müssen sicherstellen, dass 16-Bit-Ganzzahlwerte auf Little-Endian-Mikrocontrollern (z. B. ARM, TriCore) beim Serialisieren/Deserialisieren explizit gedreht werden.</li>\n<li><strong>Konfigurationsanforderungen (BSW/ECUC):</strong></li>\n<li>Parameter <code>FrArTpAddressFormatType</code>: Konfiguration auf <code>FRARTP_2_BYTE_ADDRESSING</code>.</li>\n<li>Konsistenz zwischen <code>FrArTpTargetAddress</code> / <code>FrArTpSourceAddress</code> und den korrespondierenden Modulen (<code>PduR</code>, <code>Dcm</code>, DoFR).</li>\n<li>Unterscheidung zum 1-Byte-Adressierungsmodus (<code>FRARTP_1_BYTE_ADDRESSING</code>): Das 2-Byte-Format erweitert den logischen Adressraum von 256 auf 65.536 Knoten, verdoppelt jedoch den Adress-Header-Overhead von 2 auf 4 Bytes.</li>\n</ul>"}, {"id": "FIG-63e787954ff327e2", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> PDU-Layout / Protokoll-Header-Spezifikation (Bit-/Byte-Felddefinition auf Protokollebene).</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li><strong>Plattform & Schicht:</strong> AUTOSAR Classic Platform (Release R3.2.3), Communication Stack (ComStack).</li>\n<li><strong>Modul:</strong> <code>FrArTp</code> (AUTOSAR FlexRay Transport Layer, Spezifikation SWS_FlexRayARTransportLayer nach ISO 10681-2).</li>\n<li><strong>Funktionale Einordnung:</strong> Liegt zwischen dem PDU Router (<code>PduR</code>) als oberer Schicht und dem FlexRay Interface (<code>FrIf</code>) als unterer Schicht.</li>\n<li><strong>Technischer Zweck:</strong> Definition des 32-Bit-Adress-Headers für N-PDUs im 2-Byte-Adressierungsmodus (<code>FRARTP_2_BYTE_ADDRESSING</code>). Dient der logischen Adressierung (Quell- und Ziel-Knotenidentifikation) für Punkt-zu-Punkt- (1:1) sowie Punkt-zu-Multipunkt-Verbindungen (1:n, funktional/Broadcast) über FlexRay-Netzwerke, typischerweise für Diagnosekommunikation (DoFR / UDS via ISO 14229) und Kalibrierung (XCP on FlexRay).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Dargestellte Datenstrukturen & Felder:</strong></li>\n<li><strong><code>Target Address (16 Bit)</code>:</strong></li>\n<li><strong>Größe:</strong> 2 Byte (16 Bit).</li>\n<li><strong>Position:</strong> Byte 0 und Byte 1 des Adress-Headers.</li>\n<li><strong>Codierung:</strong> Big-Endian (Network Byte Order, MSB in Byte 0, LSB in Byte 1).</li>\n<li><strong>Semantik:</strong> Logische 16-Bit-Zieladresse (Empfänger-Steuergerät bzw. funktionale Multicast-/Broadcast-Adresse).</li>\n<li><strong><code>Source Address (16 Bit)</code>:</strong></li>\n<li><strong>Größe:</strong> 2 Byte (16 Bit).</li>\n<li><strong>Position:</strong> Byte 2 und Byte 3 des Adress-Headers.</li>\n<li><strong>Codierung:</strong> Big-Endian (Network Byte Order, MSB in Byte 2, LSB in Byte 3).</li>\n<li><strong>Semantik:</strong> Logische 16-Bit-Quelladresse (sendendes Steuergerät).</li>\n<li><strong>Beziehungen, Framing & Kardinalitäten:</strong></li>\n<li><strong>Gesamtbreite des Adress-Headers:</strong> Exakt 4 Byte.</li>\n<li><strong>Kardinalität:</strong> 1:1-Paarung pro adressiertem N-PDU-Rahmen. Jeder Adress-Header besteht obligatorisch aus genau einer Target Address und genau einer Source Address.</li>\n<li><strong>PDU-Strukturierung:</strong> Der Adress-Header steht unmittelbar am Anfang der N-PDU, gefolgt von der Protocol Control Information (N-PCI) und den Nutzdaten (N-Data):</li>\n</ul>\n<p class=\"fig-p\">$$\\text{N-PDU} = \\text{Address Header (4 Bytes)} + \\text{N-PCI (1–5 Bytes)} + \\text{N-Data}$$</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Sende-Pfad (TX):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>PduR</code> initiiert die Übertragung via <code>PduR_FrArTpTransmit(TxPduId, PduInfoPtr)</code>.</li>\n<li><strong>Header-Generierung:</strong> Das Modul <code>FrArTp</code> prüft die für die Verbindung (<code>FrArTpConnection</code>) konfigurierte Adressierungsart. Bei aktivem 2-Byte-Format werden die konfigurierte Target Address (<code>FrArTpTargetAddress</code>) in Byte 0–1 und die Source Address (<code>FrArTpSourceAddress</code>) in Byte 2–3 des N-PDU-Puffers serialisiert.</li>\n<li><strong>Framing & N-PCI:</strong> Nachfolgend werden N-PCI (SF, FF, CF, FC) und SDU-Daten assembliert.</li>\n<li><strong>Übergabe:</strong> Die serialisierte PDU wird via <code>FrIf_Transmit(FrTxPduId, &amp;PduInfo)</code> an das FlexRay-Interface übergeben.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Empfangs-Pfad (RX) & Filterung:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Asynchrone Empfangsmeldung via <code>FrArTp_RxIndication(RxPduId, PduInfoPtr)</code> durch das <code>FrIf</code>.</li>\n<li><strong>Parsing:</strong> Extraktion von Byte 0–1 (TA) und Byte 2–3 (SA).</li>\n<li><strong>Adressfilterung:</strong> Abgleich von TA gegen die eigene konfigurierte Knotenadresse (physikalisch) oder Gruppenadressen (funktional).</li>\n<li><strong>Routing:</strong> Zuordnung zur entsprechenden RX-Verbindungsinstanz (<code>FrArTpRxConnection</code>) anhand des Tupels <code>(Target Address, Source Address)</code>.</li>\n<li><strong>Verwerfen/Fehlerfall:</strong> Passt TA nicht auf den lokalen Knoten oder ist kein passender Verbindungskontext konfiguriert, wird die PDU stillschweigend verworfen; bei Formatinkonsistenz oder PDU-Längenunterschreitung (< 4 Byte Adress-Header + N-PCI) erfolgt ein Report an das Default Error Tracer Modul (<code>DET</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Nutzdaten-Overhead & PDU-Budgetierung:</strong></li>\n<li>Der 2-Byte-Adress-Header verbraucht stets <strong>4 Byte Payload</strong> pro FlexRay-Frame. Bei festen statischen Slotgrößen (z. B. 16, 32 oder 64 Bytes) reduziert sich die maximale Transportdatenlänge pro Frame (Single Frame oder Consecutive Frame) entsprechend um 4 Bytes plus N-PCI-Länge.</li>\n<li><strong>Endianness & Byte-Order:</strong></li>\n<li>AUTOSAR ComStack schreibt Network Byte Order (Big-Endian) vor. Treiber- und Stack-Entwickler müssen sicherstellen, dass 16-Bit-Ganzzahlwerte auf Little-Endian-Mikrocontrollern (z. B. ARM, TriCore) beim Serialisieren/Deserialisieren explizit gedreht werden.</li>\n<li><strong>Konfigurationsanforderungen (BSW/ECUC):</strong></li>\n<li>Parameter <code>FrArTpAddressFormatType</code>: Konfiguration auf <code>FRARTP_2_BYTE_ADDRESSING</code>.</li>\n<li>Konsistenz zwischen <code>FrArTpTargetAddress</code> / <code>FrArTpSourceAddress</code> und den korrespondierenden Modulen (<code>PduR</code>, <code>Dcm</code>, DoFR).</li>\n<li>Unterscheidung zum 1-Byte-Adressierungsmodus (<code>FRARTP_1_BYTE_ADDRESSING</code>): Das 2-Byte-Format erweitert den logischen Adressraum von 256 auf 65.536 Knoten, verdoppelt jedoch den Adress-Header-Overhead von 2 auf 4 Bytes.</li>\n</ul>"}, {"id": "FIG-f73525d316a84a25", "releases": ["R20-11", "R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> PDU-Layout / Protokoll-Header-Spezifikation (Bit-/Byte-Felddefinition auf Protokollebene).</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li><strong>Plattform & Schicht:</strong> AUTOSAR Classic Platform (Release R3.2.3), Communication Stack (ComStack).</li>\n<li><strong>Modul:</strong> <code>FrArTp</code> (AUTOSAR FlexRay Transport Layer, Spezifikation SWS_FlexRayARTransportLayer nach ISO 10681-2).</li>\n<li><strong>Funktionale Einordnung:</strong> Liegt zwischen dem PDU Router (<code>PduR</code>) als oberer Schicht und dem FlexRay Interface (<code>FrIf</code>) als unterer Schicht.</li>\n<li><strong>Technischer Zweck:</strong> Definition des 32-Bit-Adress-Headers für N-PDUs im 2-Byte-Adressierungsmodus (<code>FRARTP_2_BYTE_ADDRESSING</code>). Dient der logischen Adressierung (Quell- und Ziel-Knotenidentifikation) für Punkt-zu-Punkt- (1:1) sowie Punkt-zu-Multipunkt-Verbindungen (1:n, funktional/Broadcast) über FlexRay-Netzwerke, typischerweise für Diagnosekommunikation (DoFR / UDS via ISO 14229) und Kalibrierung (XCP on FlexRay).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Dargestellte Datenstrukturen & Felder:</strong></li>\n<li><strong><code>Target Address (16 Bit)</code>:</strong></li>\n<li><strong>Größe:</strong> 2 Byte (16 Bit).</li>\n<li><strong>Position:</strong> Byte 0 und Byte 1 des Adress-Headers.</li>\n<li><strong>Codierung:</strong> Big-Endian (Network Byte Order, MSB in Byte 0, LSB in Byte 1).</li>\n<li><strong>Semantik:</strong> Logische 16-Bit-Zieladresse (Empfänger-Steuergerät bzw. funktionale Multicast-/Broadcast-Adresse).</li>\n<li><strong><code>Source Address (16 Bit)</code>:</strong></li>\n<li><strong>Größe:</strong> 2 Byte (16 Bit).</li>\n<li><strong>Position:</strong> Byte 2 und Byte 3 des Adress-Headers.</li>\n<li><strong>Codierung:</strong> Big-Endian (Network Byte Order, MSB in Byte 2, LSB in Byte 3).</li>\n<li><strong>Semantik:</strong> Logische 16-Bit-Quelladresse (sendendes Steuergerät).</li>\n<li><strong>Beziehungen, Framing & Kardinalitäten:</strong></li>\n<li><strong>Gesamtbreite des Adress-Headers:</strong> Exakt 4 Byte.</li>\n<li><strong>Kardinalität:</strong> 1:1-Paarung pro adressiertem N-PDU-Rahmen. Jeder Adress-Header besteht obligatorisch aus genau einer Target Address und genau einer Source Address.</li>\n<li><strong>PDU-Strukturierung:</strong> Der Adress-Header steht unmittelbar am Anfang der N-PDU, gefolgt von der Protocol Control Information (N-PCI) und den Nutzdaten (N-Data):</li>\n</ul>\n<p class=\"fig-p\">$$\\text{N-PDU} = \\text{Address Header (4 Bytes)} + \\text{N-PCI (1–5 Bytes)} + \\text{N-Data}$$</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Sende-Pfad (TX):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>PduR</code> initiiert die Übertragung via <code>PduR_FrArTpTransmit(TxPduId, PduInfoPtr)</code>.</li>\n<li><strong>Header-Generierung:</strong> Das Modul <code>FrArTp</code> prüft die für die Verbindung (<code>FrArTpConnection</code>) konfigurierte Adressierungsart. Bei aktivem 2-Byte-Format werden die konfigurierte Target Address (<code>FrArTpTargetAddress</code>) in Byte 0–1 und die Source Address (<code>FrArTpSourceAddress</code>) in Byte 2–3 des N-PDU-Puffers serialisiert.</li>\n<li><strong>Framing & N-PCI:</strong> Nachfolgend werden N-PCI (SF, FF, CF, FC) und SDU-Daten assembliert.</li>\n<li><strong>Übergabe:</strong> Die serialisierte PDU wird via <code>FrIf_Transmit(FrTxPduId, &amp;PduInfo)</code> an das FlexRay-Interface übergeben.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Empfangs-Pfad (RX) & Filterung:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Asynchrone Empfangsmeldung via <code>FrArTp_RxIndication(RxPduId, PduInfoPtr)</code> durch das <code>FrIf</code>.</li>\n<li><strong>Parsing:</strong> Extraktion von Byte 0–1 (TA) und Byte 2–3 (SA).</li>\n<li><strong>Adressfilterung:</strong> Abgleich von TA gegen die eigene konfigurierte Knotenadresse (physikalisch) oder Gruppenadressen (funktional).</li>\n<li><strong>Routing:</strong> Zuordnung zur entsprechenden RX-Verbindungsinstanz (<code>FrArTpRxConnection</code>) anhand des Tupels <code>(Target Address, Source Address)</code>.</li>\n<li><strong>Verwerfen/Fehlerfall:</strong> Passt TA nicht auf den lokalen Knoten oder ist kein passender Verbindungskontext konfiguriert, wird die PDU stillschweigend verworfen; bei Formatinkonsistenz oder PDU-Längenunterschreitung (< 4 Byte Adress-Header + N-PCI) erfolgt ein Report an das Default Error Tracer Modul (<code>DET</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Nutzdaten-Overhead & PDU-Budgetierung:</strong></li>\n<li>Der 2-Byte-Adress-Header verbraucht stets <strong>4 Byte Payload</strong> pro FlexRay-Frame. Bei festen statischen Slotgrößen (z. B. 16, 32 oder 64 Bytes) reduziert sich die maximale Transportdatenlänge pro Frame (Single Frame oder Consecutive Frame) entsprechend um 4 Bytes plus N-PCI-Länge.</li>\n<li><strong>Endianness & Byte-Order:</strong></li>\n<li>AUTOSAR ComStack schreibt Network Byte Order (Big-Endian) vor. Treiber- und Stack-Entwickler müssen sicherstellen, dass 16-Bit-Ganzzahlwerte auf Little-Endian-Mikrocontrollern (z. B. ARM, TriCore) beim Serialisieren/Deserialisieren explizit gedreht werden.</li>\n<li><strong>Konfigurationsanforderungen (BSW/ECUC):</strong></li>\n<li>Parameter <code>FrArTpAddressFormatType</code>: Konfiguration auf <code>FRARTP_2_BYTE_ADDRESSING</code>.</li>\n<li>Konsistenz zwischen <code>FrArTpTargetAddress</code> / <code>FrArTpSourceAddress</code> und den korrespondierenden Modulen (<code>PduR</code>, <code>Dcm</code>, DoFR).</li>\n<li>Unterscheidung zum 1-Byte-Adressierungsmodus (<code>FRARTP_1_BYTE_ADDRESSING</code>): Das 2-Byte-Format erweitert den logischen Adressraum von 256 auf 65.536 Knoten, verdoppelt jedoch den Adress-Header-Overhead von 2 auf 4 Bytes.</li>\n</ul>"}], "trans": [{"from": "FIG-cfebc6be27fb2711", "to": "FIG-8e478ed3be09459c", "fr": "R3.2.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Header-Beschriftung:</strong> Ergänzung der Beschriftung „2 Byte Addressing Not compliant to ISO 15765-2“ oberhalb der Adressfelder.</li>\n</ul>"}, {"from": "FIG-8e478ed3be09459c", "to": "FIG-63e787954ff327e2", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-63e787954ff327e2", "to": "FIG-f73525d316a84a25", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
